const H=this.helpers;
const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const r={};
async function g(u){return await H.httpRequest({method:'GET',url:u,json:true,headers:{'User-Agent':UA,'Accept':'application/json'}});}
try{
  // find bella-elite in the list
  let found=null, pagesChecked=0;
  for(let page=1;page<=8;page++){
    const res=await g('https://www.lentillesmaroc.ma/wp-json/wc/store/products?per_page=100&page='+page);
    const arr=Array.isArray(res)?res:(res&&res.products?res.products:[]);
    pagesChecked++;
    if(!arr.length) break;
    for(const p of arr){ if(String(p.permalink||'').includes('bella-elite-collection')){ found=p; break; } }
    if(found) break;
    if(arr.length<100) break;
  }
  r.pagesChecked=pagesChecked;
  if(found){
    r.id=found.id; r.permalink=found.permalink; r.type=found.type;
    r.hasShortDesc=('short_description' in found);
    r.shortDescLen=(found.short_description||'').length;
    r.shortDescSnippet=String(found.short_description||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,220);
    r.keys=Object.keys(found);
  } else { r.note='bella-elite not found in list'; }
  // compare with single endpoint
  const one=await g('https://www.lentillesmaroc.ma/wp-json/wc/store/products/526');
  const o=one||{};
  r.singleShortDescLen=(o.short_description||'').length;
  r.singleSnippet=String(o.short_description||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,220);
}catch(e){ r.error=String((e&&e.message)||e).slice(0,300); }
return [{json:r}];
